using System; using System.IO; using System.Threading.Tasks; using Microsoft.VisualStudio.TestTools.UnitTesting; using TaskTree.Modules.AutoUpdater;
namespace TaskTree.Modules.AutoUpdater.Tests{[TestClass]public class RollbackServiceTests{static string R(){var p=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString("N"));return p;}[TestMethod]public async Task FindLastKnownGoodAsync_NoDirectory_ReturnsNull(){Assert.IsNull(await new RollbackService(R()).FindLastKnownGoodAsync());}[TestMethod]public async Task FindLastKnownGoodAsync_NoMsix_ReturnsNull(){var r=R();Directory.CreateDirectory(r);File.WriteAllText(Path.Combine(r,"x.txt"),"x");Assert.IsNull(await new RollbackService(r).FindLastKnownGoodAsync());}[TestMethod]public async Task FindLastKnownGoodAsync_ReturnsNewestMsix(){var r=R();Directory.CreateDirectory(r);var a=Path.Combine(r,"a.msix");var b=Path.Combine(r,"b.msix");File.WriteAllText(a,"a");File.WriteAllText(b,"b");File.SetLastWriteTimeUtc(a,DateTime.UtcNow.AddMinutes(-1));File.SetLastWriteTimeUtc(b,DateTime.UtcNow);Assert.AreEqual(b,await new RollbackService(r).FindLastKnownGoodAsync());}[TestMethod]public async Task RollbackAsync_MissingLastKnownGoodPackage_FailsClosed(){var ex=await Assert.ThrowsExceptionAsync<FileNotFoundException>(()=>new RollbackService(R()).RollbackAsync());StringAssert.Contains(ex.Message,"last-known-good");}[TestMethod]public void Constructor_InvalidRoot_Throws(){Assert.ThrowsException<ArgumentException>(()=>new RollbackService(""));}}
